import { rng } from "./util";

/**
 * Symbol 0 marks the boundary of a name: it pads the context at the start and is the
 * transition target that ends a name.
 */
const BOUNDARY = 0;

type Row = {
    symbols: Uint8Array,
    cumulative: Uint32Array,
    total: number,
}

/**
 * Character-level Markov chain generated by ~/ideaprojects/naminator. Symbol i + 1 is
 * alphabet[i], rows maps a context key (its symbols as char codes) to the weighted
 * next symbols.
 */
export type Chain = {
    order: number,
    alphabet: string[],
    rows: Map<string, Row>,
}

/**
 * Decodes naminator's base64 chain data. See naminator's codec.js for the format.
 */
export function decodeChain(base64 : string) : Chain
{
    const bytes = Uint8Array.from(atob(base64), c => c.charCodeAt(0));
    let pos = 0;

    function readVarint()
    {
        let n = 0, shift = 0, b;
        do
        {
            b = bytes[pos++];
            n |= (b & 127) << shift;
            shift += 7;
        } while (b & 128);
        return n;
    }

    const version = bytes[pos++];
    if (version !== 1)
    {
        throw new Error("Unsupported name data version " + version);
    }
    const order = bytes[pos++];
    const alphabetLength = readVarint();
    const alphabet = Array.from(new TextDecoder().decode(bytes.subarray(pos, pos + alphabetLength)));
    pos += alphabetLength;

    const rows = new Map<string, Row>();
    const context : number[] = [];
    function readTrie(depth : number)
    {
        const size = readVarint();
        for (let i = 0; i < size; i++)
        {
            context.push(bytes[pos++]);
            if (depth < order)
            {
                readTrie(depth + 1);
            }
            else
            {
                const entries = readVarint();
                const symbols = new Uint8Array(entries);
                const cumulative = new Uint32Array(entries);
                let total = 0;
                for (let j = 0; j < entries; j++)
                {
                    symbols[j] = bytes[pos++];
                    total += readVarint();
                    cumulative[j] = total;
                }
                rows.set(String.fromCharCode(...context), { symbols, cumulative, total });
            }
            context.pop();
        }
    }
    readTrie(1);

    return { order, alphabet, rows };
}

function pick(row : Row)
{
    const r = Math.floor(row.total * rng.next());
    let i = 0;
    while (row.cumulative[i] <= r)
    {
        i++;
    }
    return row.symbols[i];
}

export default function nameGenerator(minLength : number, dataSet = PEOPLE)
{
    const { order, alphabet, rows } = dataSet;

    for (;;)
    {
        const context = new Array<number>(order).fill(BOUNDARY);
        const title : string[] = [];
        for (;;)
        {
            const s = pick(rows.get(String.fromCharCode(...context))!);
            if (s === BOUNDARY)
            {
                break;
            }

            const letter = alphabet[s - 1];
            const c = title[title.length - 1];
            title.push(c === undefined || c === " " || c === "'" ? letter.toUpperCase() : letter);

            context.shift();
            context.push(s);
        }

        if (title.length >= minLength)
        {
            return title.join("");
        }
    }
}

